update cellar.products set proof = 117.8, producer = coalesce(producer, 'Angel''s Envy'), producer_id = coalesce(producer_id, '19cdb4d2-ae9f-4a5e-82ae-007a20e88a61'::uuid), source = 'maker', source_url = 'https://www.angelsenvy.com/us/en/whiskeys/cask-strength/15th-edition-cask-strength-bourbon/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '1fccfa84-b6ad-47fa-9586-312bed80830c' and facts_verified_at is null;
