update cellar.products set finish = 'Rum Casks', producer = coalesce(producer, 'Angel''s Envy'), producer_id = coalesce(producer_id, '19cdb4d2-ae9f-4a5e-82ae-007a20e88a61'::uuid), source_url = 'https://www.angelsenvy.com/us/en/whiskeys/signature-series/rum-cask-finished-rye/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'd09fb1dc-1062-4829-8620-f7f00424bacf' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('1fccfa84-b6ad-47fa-9586-312bed80830c', '7755aa39-9e75-4f4c-ba82-70cc9b499422', 'd09fb1dc-1062-4829-8620-f7f00424bacf');
insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://d3cqmwe6z7cbal.cloudfront.net/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
